const SRC_IN_ENTRY: &str = "def ir_it_in_entry (g1 : IRFunc) (g2 : IRFunc) (x : IRItIn) : IRList Nat -> IRList IRFrame -> IRMachine := @IRItIn.rec (fun (_ : IRItIn) => IRList Nat -> IRList IRFrame -> IRMachine) (fun (p : Nat) (q : Nat) (mem : IRList IRMemSlot) (na : Nat) => ir_it_ag_entry p q mem na) (fun (p : Nat) (mem : IRList IRMemSlot) (na : Nat) => ir_it_hb_entry g1 p mem na) (fun (p : Nat) (q : Nat) (mem : IRList IRMemSlot) (na : Nat) => ir_it_fast_entry g2 p q mem na) x";

const SRC_IN_POST: &str = "def ir_it_in_post (QH : Nat -> IRList IRMemSlot -> Nat -> IRList IRMemSlot -> Nat -> IRList IRScalar -> Prop) (QF : Nat -> Nat -> IRList IRMemSlot -> Nat -> IRList IRMemSlot -> Nat -> IRList IRScalar -> Prop) (x : IRItIn) : IRList IRMemSlot -> Nat -> IRList IRScalar -> Prop := @IRItIn.rec (fun (_ : IRItIn) => IRList IRMemSlot -> Nat -> IRList IRScalar -> Prop) (fun (p : Nat) (q : Nat) (mem : IRList IRMemSlot) (na : Nat) => ir_it_tpost QH QF p q mem na) QH QF x";

